13	/**
14	 * Conversation template config
15	 */
16	export interface ConvTemplateConfig {
17	  system_template: string;
18	  system_message: string;
19	  roles: Record<Role, string>;
20	  role_templates?: Partial<Record<Role, string>>;
21	  seps: Array<string>;
22	  role_content_sep?: string;
23	  role_empty_sep?: string;
24	  stop_str: Array<string>;
25	  system_prefix_token_ids?: Array<number>;
26	  stop_token_ids: Array<number>;
27	  add_role_after_system_message?: boolean;
28	}
