67	/**
68	 * Information about the tokenizer. Currently, only `token_postproc_method` is used to
69	 * post process the token table when using grammar.
70	 */
71	export interface TokenizerInfo {
72	  token_postproc_method: string;
73	  prepend_space_in_encode: boolean;
74	  strip_space_in_decode: boolean;
75	}
76	
77	/**
78	 * Config of one chat model, a data structure representing `mlc-chat-config.json`.
79	 * This only corresponds to the chat-related fields and `tokenizer_files` of `mlc-chat-config.json`.
80	 * Only these fields affect the conversation in runtime.
81	 * i.e. The third part in https://llm.mlc.ai/docs/get_started/mlc_chat_config.html.
82	 *
83	 * This is initialized in `MLCEngine.reload()` with the model's `mlc-chat-config.json`.
84	 */
85	export interface ChatConfig {
86	  // First three fields affect the entire conversation, i.e. used in `MLCEngine.reload()`
87	  tokenizer_files: Array<string>;
88	  tokenizer_info?: TokenizerInfo;
89	  token_table_postproc_method?: string; // TODO: backward compatibility, remove soon
90	  vocab_size: number;
91	  conv_config?: Partial<ConvTemplateConfig>;
92	  conv_template: ConvTemplateConfig;
93	  // KVCache settings
94	  context_window_size: number;
95	  sliding_window_size: number;
96	  attention_sink_size: number;
97	  // RNNState settings (for hybrid/recurrent models). If unspecified, runtime picks a safe default.
98	  max_history_size?: number;
99	  // Fields below can be swapped per-generation via `GenerationConfig`
100	  // Fields only used in MLC
101	  repetition_penalty: number;
102	  // Fields shared by MLC and OpenAI APIs
103	  frequency_penalty: number;
104	  presence_penalty: number;
105	  top_p: number;
106	  temperature: number;
107	  bos_token_id?: number;
108	  // Model type identifier from mlc-chat-config.json (e.g. "phi3_v", "gemma3_v")
109	  model_type?: string;
110	  // Nested model config from mlc-chat-config.json, contains model-specific parameters
111	  model_config?: VisionModelConfig & Record<string, unknown>;
112	}
