114	/**
115	 * Custom options that can be used to override known config values.
116	 */
117	// eslint-disable-next-line @typescript-eslint/no-empty-object-type
118	export interface ChatOptions extends Partial<ChatConfig> {}
119	
120	/**
121	 * Optional configurations for `CreateMLCEngine()` and `CreateWebWorkerMLCEngine()`.
122	 *
123	 * appConfig: Configure the app, including model list and persistent cache backend.
124	 * initProgressCallback: A callback for showing the progress of loading the model.
125	 * logitProcessorRegistry: A register for stateful logit processors, see `webllm.LogitProcessor`.
126	 *
127	 * @note All fields are optional, and `logitProcessorRegistry` is only used for `MLCEngine` and not
128	 * other `MLCEngine`s.
129	 */
130	export interface MLCEngineConfig {
131	  appConfig?: AppConfig;
132	  initProgressCallback?: InitProgressCallback;
133	  logitProcessorRegistry?: Map<string, LogitProcessor>;
134	  logLevel?: LogLevel;
135	}
136	
137	/**
138	 * Config for a single generation.
139	 * Essentially `ChatConfig` without `tokenizer_files`, `conv_config`, or `conv_template`.
140	 * We also support additional fields not present in `mlc-chat-config.json` due to OpenAI-like APIs.
141	 *
142	 * Note that all values are optional. If unspecified, we use whatever values in `ChatConfig`
143	 * initialized during `MLCEngine.reload()`.
144	 */
145	export interface GenerationConfig {
146	  // Only used in MLC
147	  repetition_penalty?: number | null;
148	  ignore_eos?: boolean;
149	  // Shared by MLC and OpenAI APIs
150	  top_p?: number | null;
151	  temperature?: number | null;
152	  // Only in OpenAI APIs
153	  max_tokens?: number | null;
154	  frequency_penalty?: number | null;
155	  presence_penalty?: number | null;
156	  stop?: string | null | Array<string>;
157	  n?: number | null;
158	  logit_bias?: Record<string, number> | null;
159	  logprobs?: boolean | null;
160	  top_logprobs?: number | null;
161	  response_format?: ResponseFormat | null;
162	  // extra_body in ChatCompletionsRequest
163	  enable_thinking?: boolean | null;
164	  enable_latency_breakdown?: boolean | null;
165	}
166	
167	export function postInitAndCheckGenerationConfigValues(
168	  config: GenerationConfig,
169	): void {
170	  function _hasValue(value: any): boolean {
171	    // if we use `if value` directly, `value` being 0 evaluates to false, violating semantics
172	    return value !== undefined && value !== null;
173	  }
174	  if (
175	    config.frequency_penalty &&
176	    (config.frequency_penalty < -2.0 || config.frequency_penalty > 2.0)
177	  ) {
178	    throw new RangeError("frequency_penalty", -2.0, 2.0);
179	  }
180	  if (
181	    config.presence_penalty &&
182	    (config.presence_penalty < -2.0 || config.presence_penalty > 2.0)
183	  ) {
184	    throw new RangeError("presence_penalty", -2.0, 2.0);
185	  }
186	  if (_hasValue(config.repetition_penalty) && config.repetition_penalty! <= 0) {
187	    throw new MinValueError("repetition_penalty", 0);
188	  }
189	  if (_hasValue(config.max_tokens) && config.max_tokens! <= 0) {
190	    throw new MinValueError("max_tokens", 0);
191	  }
192	  if ((_hasValue(config.top_p) && config.top_p! <= 0) || config.top_p! > 1) {
193	    throw new RangeError("top_p", 0, 1);
194	  }
195	  if (_hasValue(config.temperature) && config.temperature! < 0) {
196	    throw new NonNegativeError("temperature");
197	  }
198	  // If only one of frequency or presence penatly is set, make the other one 0.0
199	  if (
200	    _hasValue(config.frequency_penalty) &&
201	    !_hasValue(config.presence_penalty)
202	  ) {
203	    config.presence_penalty = 0.0;
204	    log.warn("Only frequency_penalty is set; we default presence_penaty to 0.");
205	  }
206	  if (
207	    _hasValue(config.presence_penalty) &&
208	    !_hasValue(config.frequency_penalty)
209	  ) {
210	    config.frequency_penalty = 0.0;
211	    log.warn(
212	      "Only presence_penalty is set; we default frequency_penalty to 0.",
213	    );
214	  }
215	  // Check logit_bias range
216	  if (_hasValue(config.logit_bias)) {
217	    for (const tokenID in config.logit_bias) {
218	      const bias = config.logit_bias[tokenID];
219	      if (bias > 100 || bias < -100) {
220	        throw new RangeError(
221	          "logit_bias",
222	          -100,
223	          100,
224	          "Got " + bias + " for tokenID " + tokenID,
225	        );
226	      }
227	      if (isNaN(parseInt(tokenID))) {
228	        throw new InvalidNumberStringError("logit_bias's keys", tokenID);
229	      }
230	    }
231	  }
232	  // logprobs and top_logprobs
233	  if (_hasValue(config.top_logprobs)) {
234	    // If top_logprobs is non-null, logprobs must be true
235	    if (!config.logprobs) {
236	      throw new DependencyError("top_logprobs", "logprobs", true);
237	    }
238	    // top_logprobs should be in range [0,5]
239	    if (config.top_logprobs! < 0 || config.top_logprobs! > 5) {
240	      throw new RangeError("top_logprobs", 0, 5, "Got " + config.top_logprobs);
241	    }
242	  }
243	  // If defined logprobs but not top_logprobs, simply make it 0
244	  if (config.logprobs) {
245	    if (!_hasValue(config.top_logprobs)) {
246	      config.top_logprobs = 0;
247	    }
248	  }
249	}
