257	/**
258	 * Information for a model.
259	 * @param model: the huggingface link to download the model weights, accepting four formats:
260	 *    - https://huggingface.co/{USERNAME}/{MODEL}, which we automatically use the main branch
261	 *    - https://huggingface.co/{USERNAME}/{MODEL}/, which we automatically use the main branch
262	 *    - https://huggingface.co/{USERNAME}/{MODEL}/resolve/{BRANCH}
263	 *    - https://huggingface.co/{USERNAME}/{MODEL}/resolve/{BRANCH}/
264	 * @param model_id: what we call the model.
265	 * @param model_lib: link to the model library (wasm file) the model uses.
266	 * @param overrides: partial ChatConfig to override mlc-chat-config.json; can be used to change KVCache settings.
267	 * @param vram_required_MB: amount of vram in MB required to run the model (can use
268	 *    `utils/vram_requirements` to calculate).
269	 * @param low_resource_required: whether the model can run on limited devices (e.g. Android phone).
270	 * @param buffer_size_required_bytes: required `maxStorageBufferBindingSize`, different for each device.
271	 * @param required_features: feature needed to run this model (e.g. shader-f16).
272	 * @param model_type: the intended usecase for the model, if unspecified, default to LLM.
273	 * @param integrity: optional SRI hashes to verify downloaded artifacts. See {@link ModelIntegrity}.
274	 */
275	export interface ModelRecord {
276	  model: string;
277	  model_id: string;
278	  model_lib: string;
279	  overrides?: ChatOptions;
280	  vram_required_MB?: number;
281	  low_resource_required?: boolean;
282	  buffer_size_required_bytes?: number;
283	  required_features?: Array<string>;
284	  model_type?: ModelType;
285	  integrity?: ModelIntegrity;
286	}
287	
288	/**
289	 * Extra configuration that can be
290	 * passed to the load.
291	 *
292	 * @param model_list: models to be used.
293	 * @param cacheBackend: the backend to use for caching models and other artifacts.
294	 * If unspecified, will use the Cache API. For more information, see:
295	 * https://developer.mozilla.org/en-US/docs/Web/API/Storage_API/Storage_quotas_and_eviction_criteria#what_technologies_store_data_in_the_browser
296	 * Supported values are:
297	 * - "cache": browser Cache API.
298	 * - "indexeddb": IndexedDB-backed cache.
299	 * - "cross-origin": Chrome Cross-Origin Storage extension-backed cache.
300	 * - "opfs": Origin Private File System-backed cache.
301	 *
302	 * @param opfsAccessMode: optional OPFS access mode. Only used when cacheBackend
303	 * is "opfs".
304	 * - "async": use async OPFS file APIs. This is the default.
305	 * - "sync": require OPFS sync access handles.
306	 * - "auto": use sync access handles when available and fall back to async OPFS otherwise.
307	 *
308	 * @note Note that the Cache API is the most well-tested in WebLLM as of now.
309	 */
310	export type CacheBackend = "cache" | "indexeddb" | "cross-origin" | "opfs";
311	export type OPFSAccessMode = "async" | "sync" | "auto";
312	
313	export interface AppConfig {
314	  model_list: Array<ModelRecord>;
315	  cacheBackend?: CacheBackend;
316	  opfsAccessMode?: OPFSAccessMode;
317	}
318	
319	export function getCacheBackend(appConfig: AppConfig): CacheBackend {
320	  if (appConfig.cacheBackend !== undefined) {
321	    return appConfig.cacheBackend;
322	  }
323	  return "cache";
324	}
