  request = {
    stream: true,
    stream_options: { include_usage: true },
    messages: [
      {
        role: "user",
        content: "How many r's are there in the word strawberry?",
      },
    ],
    extra_body: {
      enable_thinking: false,
    },
  };
  await streamResponse(engine, request);

